27:- `onError` and `afterSession` hooks now fire when `beforeSession` throws, matching the guarantee the hook names imply. Previously, a throw from `beforeSession` escaped the `try`/`finally` block en
---
diff --git a/src/orchestration/chatOrchestrator.ts b/src/orchestration/chatOrchestrator.ts
index 8defbd2..ccc9d67 100644
--- a/src/orchestration/chatOrchestrator.ts
+++ b/src/orchestration/chatOrchestrator.ts
@@ -147,8 +147,8 @@ export function createChatOrchestrator(

         if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
       } catch (error) {
-        if (hooks?.onError && error instanceof Error) {
-          await hooks.onError(session, error);
+        if (hooks?.onError) {
+          await hooks.onError(session, toError(error));
         }
         throw error;
       } finally {
@@ -164,6 +164,21 @@ export function createChatOrchestrator(
   };
 }

+// The caller still gets the original rejection; onError gets an Error wrapping it as `cause`.
+function toError(reason: unknown): Error {
+  if (reason instanceof Error) return reason;
+  return new Error(readableMessage(reason), {cause: reason});
+}
+
+function readableMessage(reason: unknown): string {
+  if (typeof reason === 'string') return reason;
+  try {
+    return JSON.stringify(reason) ?? String(reason);
+  } catch {
+    return String(reason);
+  }
+}
+
 // A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
 function normalizeToolRounds(value: number | undefined): number {
   if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
